 "", place_type: "dining"}, {gmap_id: "0x88dd7f8130e37b3b:0x82c8db0c77d2bda9", price_level: "medium", accessibility: "boolean", waterfront: "false", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88dd7f8130e37b3b:0x82c8db0c77d2bda9", price_level: "affordable", accessibility: "false", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88dd7f8130e37b3b:0x82c8db0c77d2bda9", price_level: "expensive", accessibility: "null", waterfront: "false", cuisine: "", audience: "", place_type: "string"}] AS row
