    SET p.price_level = row.price_level, 
        p.accessibility = row.accessibility, 
        p.waterfront = row.waterfront
    
    MERGE (c:Cuisine {name: row.cuisine})
    MERGE (a:Audience {name: row.audience})
    MERGE (t:PlaceType {name: row.place_type})
    
    MERGE (p)-[:SERVES]->(c)
    MERGE (p)-[:TARGETS]->(a)
    MERGE (p)-[:IS_TYPE]->(t)
    RETURN count(p)
$$) AS (v agtype);


