"", place_type: "drive-thru"}, {gmap_id: "0x88c2edae50b00a9f:0x56674f943986d173", price_level: "medium", accessibility: "false", waterfront: "False", cuisine: "", audience: "", place_type: "drive-thru"}] AS row
