erfront: "false", cuisine: "", audience: "", place_type: "drive-thru"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "medium", accessibility: "true", waterfront: "false", cuisine: "", audience: "", place_type: "Fast Food"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable", accessibility: "boolean", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "medium", accessibility: "false", waterfront: "false", cuisine: "", audience: "", place_type: "restaurant"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable/medium/expensive", accessibility: "boolean", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable", accessibility: "boolean", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable/medium/expensive", accessibility: "boolean or null", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable/medium/expensive", accessibility: "null", waterfront: "False", cuisine: "", audience: "", place_type: "string"}, {gmap_id: "0x88e77c4a94a8278b:0x391d52e0b192f1d3", price_level: "affordable", accessibility: "boolean", waterfront: "False", cuisine: "", audience: "", place_type: "restaurant"}] AS row
